T["Bzzzzttt Bzzzzztt\nExplosion!"] = "バチチチチッ　バチチチチチッ\nバクハツ！"
T["I don't think this one will be easy...{pause:0.4}\nLet's do our very best!"] = "こいつは手ごわそう……{pause:0.4}\nせいいっぱい、がんばろう！"
T["You who entered this place...\nShall be punished..."] = "この地に足を踏み入れし者よ……\n罰を受けるがよい……"
T["But... It's you who..."] = "で、でも……それは、そっちのほうが……"
T["Ah...\nLet's do it, <player name>!"] = "あ……\nやろう、<player name>！"
